#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="E:\work\frontend-monorepo\tools\react-scripts\bin\node_modules;E:\work\frontend-monorepo\tools\react-scripts\node_modules;E:\work\frontend-monorepo\tools\node_modules;E:\work\frontend-monorepo\node_modules;E:\work\node_modules;E:\node_modules;E:\work\frontend-monorepo\libs\ot_105_2_0020\node_modules;E:\work\frontend-monorepo\libs\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/e/work/frontend-monorepo/tools/react-scripts/bin/node_modules:/mnt/e/work/frontend-monorepo/tools/react-scripts/node_modules:/mnt/e/work/frontend-monorepo/tools/node_modules:/mnt/e/work/frontend-monorepo/node_modules:/mnt/e/work/node_modules:/mnt/e/node_modules:/mnt/e/work/frontend-monorepo/libs/ot_105_2_0020/node_modules:/mnt/e/work/frontend-monorepo/libs/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$env_node_path$pathsep$new_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../../../../tools/react-scripts/bin/react-scripts.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../../../../tools/react-scripts/bin/react-scripts.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../../../../tools/react-scripts/bin/react-scripts.js" $args
  } else {
    & "node$exe"  "$basedir/../../../../tools/react-scripts/bin/react-scripts.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
